//! Color calibrations for cameras whose raw files carry none (every format
//! but DNG), in the DNG specification's terms: each camera's two
//! calibrations (Standard Illuminant A and D65, as a rule), so a develop
//! can use the DNG color model (color::camera_to_xyz_d50), which follows
//! the light of the scene, rather than one daylight matrix for every
//! scene. The table (calibrations.rs) is generated by heeler-raw's
//! examples/calibrations.rs from DNGs a converter wrote from the corpus's
//! files, one a camera. Every camera takes its row here, never a matrix
//! its own files write in their maker notes.

use crate::color::Profile;

/// One camera's calibration. A matrix is nine values, row by row.
#[derive(Debug)]
pub struct Calibration {
    pub make: &'static str,
    pub model: &'static str,
    /// EXIF LightSource codes of the two calibrations (17 Standard A, 21
    /// D65, ...); 0 for a calibration the profile lacks.
    pub illuminants: [u32; 2],
    pub color_matrix: [Option<[f64; 9]>; 2],
    pub forward_matrix: [Option<[f64; 9]>; 2],
    /// Whether the profile also has hue and saturation tables, which the
    /// matrices alone do not reproduce (some profiles keep most of their
    /// color correction there).
    pub tables: bool,
}

include!("calibrations.rs");

/// A camera's calibration by Make and Model as its files give them: an
/// exact match first, then one that differs only in case and spacing.
pub fn find(make: &str, model: &str) -> Option<&'static Calibration> {
    let norm = |s: &str| s.split_whitespace().collect::<Vec<_>>().join(" ").to_ascii_lowercase();
    CALIBRATIONS.iter().find(|c| c.make == make && c.model == model).or_else(|| {
        let (mk, md) = (norm(make), norm(model));
        CALIBRATIONS.iter().find(|c| norm(c.make) == mk && norm(c.model) == md)
    })
}

/// Every calibration in the table.
pub fn all() -> &'static [Calibration] {
    CALIBRATIONS
}

impl Calibration {
    /// The calibration as a DNG profile, for color::camera_to_xyz_d50.
    pub fn profile(&self) -> Profile {
        let m = |v: &Option<[f64; 9]>| v.as_ref().and_then(|v| crate::color::as3(v));
        Profile {
            illuminants: self.illuminants,
            color_matrix: [m(&self.color_matrix[0]), m(&self.color_matrix[1])],
            camera_calibration: [None, None],
            forward_matrix: [m(&self.forward_matrix[0]), m(&self.forward_matrix[1])],
            analog_balance: None,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::color::{apply, camera_to_xyz_d50, invert3, D50};

    #[test]
    fn every_calibration_takes_the_cameras_white_to_d50() {
        assert!(all().len() > 100, "the table has {} cameras", all().len());
        for c in all() {
            let p = c.profile();
            let cm = p.color_matrix[0].expect("a ColorMatrix1");
            assert!(invert3(&cm).is_some(), "{} {}: a singular matrix", c.make, c.model);
            // The camera's response to D65 white, through the model.
            let neutral = apply(p.color_matrix[1].as_ref().unwrap_or(&cm), apply(&crate::color::XYZ_FROM_SRGB, [1.0; 3]));
            let m = camera_to_xyz_d50(&p, neutral).unwrap_or_else(|| panic!("{} {}", c.make, c.model));
            let w = apply(&m, neutral);
            for ch in 0..3 {
                assert!((w[ch] / w[1] - D50[ch]).abs() < 5e-3, "{} {}: white {w:?}", c.make, c.model);
            }
        }
    }

    #[test]
    fn cameras_are_found_by_their_make_and_model() {
        let c = find("SONY", "ILCE-7M3").expect("the Sony ILCE-7M3");
        assert_eq!(c.illuminants, [17, 21]);
        assert!(find("sony", "ILCE-7M3").is_some(), "case and spacing are forgiven");
        assert!(find("SONY", "ILCE-7M9").is_none());
    }
}
